mapper.select:
SELECT p.policy_id
FROM tb_system_policy p
WHERE p.tenant_id = #{tenantId}
  AND p.policy_code = #{policyCode}

SELECT EXISTS (
    SELECT 1
    FROM tb_sales_delivery_plan_hd h
    WHERE h.tenant_id = #{tenantId}
)

mapper.update:
UPDATE tb_tenant
SET delivery_plan_mode = #{value}
WHERE tenant_id = #{tenantId}
  AND #{value} IN ('AUTO', 'MANUAL')

UPDATE tb_tenant
SET over_delivery_policy = #{value}
WHERE tenant_id = #{tenantId}
  AND #{value} IN ('BLOCK', 'WARN')

mapper.delete:
DELETE FROM tb_system_policy
WHERE tenant_id = #{tenantId}
  AND policy_id = #{policyId}
  AND version = #{version}
  AND system_policy_at = 'N'

